xql_query:
// ============================================================
// Rule: MS_Teams Federation Settings Modified
// Vendor: Microsoft 365
// Objective:
// Detect activity associated with MS_Teams Federation Settings Modified.
// Severity: SEV_050_CRITICAL
// Category: TAMPERING
// ============================================================
// MITRE ATT&CK:
// Tactic: TA0005 - Defense Evasion
// Technique: T1484.002 - Domain Policy Modification: Domain Trust Modification

// Title: Microsoft Teams Tenant Federation Settings Modified
// Description:
// Detecta alterações em configurações sensíveis de federação e acesso externo do Microsoft Teams,
// incluindo comunicação com usuários federados, consumidores Teams, domínios permitidos/bloqueados,
// trial tenants e parâmetros de controle de confiança entre tenants.
//
// Data Source: saas_audit_logs
// Workload: MicrosoftTeams
// Operation: TeamsAdminAction
// MITRE ATT&CK:
// - TA0107 - Defense Impairment
// - TA0004 - Privilege Escalation
// - T1484.002 - Domain or Tenant Policy Modification: Trust Modification

config case_sensitive = false

| dataset = saas_audit_logs

// Pré-filtro para reduzir o volume de eventos processados.
// Busca somente logs relacionados a ações administrativas no Microsoft Teams,
// especificamente alterações em TenantFederationSettings.
| filter raw_log contains "MicrosoftTeams"
    and raw_log contains "TeamsAdminAction"
    and raw_log contains "TenantFederationSettings"
    and raw_log contains "ModifiedProperties"

// Extração dos principais campos do evento bruto.
// Esses campos ajudam a identificar quem realizou a alteração,
// onde a alteração ocorreu e qual objeto/política foi modificada.
| alter
    creation_time = json_extract_scalar(raw_log, "$.CreationTime"),
    operation = json_extract_scalar(raw_log, "$.Operation"),
    workload = json_extract_scalar(raw_log, "$.Workload"),
    result_status = json_extract_scalar(raw_log, "$.ResultStatus"),
    user_id = json_extract_scalar(raw_log, "$.UserId"),
    user_key = json_extract_scalar(raw_log, "$.UserKey"),
    client_ip = json_extract_scalar(raw_log, "$.ClientIP"),
    object_id = json_extract_scalar(raw_log, "$.ObjectId"),
    admin_action_detail = json_extract_scalar(raw_log, "$.AdminActionDetail"),
    client_application = json_extract_scalar(raw_log, "$.ClientApplication"),
    user_claims = json_extract_scalar(raw_log, "$.UserClaims"),
    modified_properties = json_extract_array(raw_log, "$.ModifiedProperties")

// Considera apenas alterações concluídas com sucesso.
| filter result_status = "Succeeded"

// Expande o array ModifiedProperties.
// Cada propriedade alterada passa a ser tratada como um evento individual,
// permitindo identificar exatamente qual parâmetro foi alterado.
| arrayexpand modified_properties

// Extração dos detalhes da propriedade modificada.
// property_name: nome do parâmetro alterado.
// old_value: valor anterior.
// new_value: novo valor configurado.
| alter
    property_name = json_extract_scalar(to_json_string(modified_properties), "$.Name"),
    old_value = json_extract_scalar(to_json_string(modified_properties), "$.OldValue"),
    new_value = json_extract_scalar(to_json_string(modified_properties), "$.NewValue")

// Monitora somente parâmetros sensíveis de federação e acesso externo do Teams.
// Esses parâmetros podem impactar comunicação externa, confiança entre tenants,
// acesso de usuários federados e interação com usuários consumidores do Teams.
| filter property_name in (
    "BlockedDomains",
    "AllowedTrialTenantDomains",
    "AllowFederatedUsers",
    "AllowTeamsConsumer",
    "AllowTeamsConsumerInbound",
    "TreatDiscoveredPartnersAsUnverified",
    "SharedSipAddressSpace",
    "RestrictTeamsConsumerToExternalUserProfiles",
    "BlockAllSubdomains",
    "ExternalAccessWithTrialTenants",
    "DomainBlockingForMoAdminsInTeams"
)

// Garante que a propriedade realmente teve alteração de valor.
// Evita gerar alerta quando o campo aparece no log, mas não representa mudança efetiva.
| filter old_value != new_value

// Campos finais para investigação e composição do alerta.
| fields
    _time,
    creation_time,
    workload,
    operation,
    result_status,
    user_id,
    user_key,
    client_ip,
    object_id,
    admin_action_detail,
    client_application,
    user_claims,
    property_name,
    old_value,
    new_value

| sort desc _time
